a = ['000100', '101101', '111111', '110100', '111011', '001110']
b = 0

def f(p, q, r):
    global b
    if p < 0 or q < 0 or p >= 6 or q >= 6:
        return
    if a[p][q] == '0':
        return
    b += r
    a[p] = a[p][:q] + '0' + a[p][q+1:]
    f(p-1, q, r+1)
    f(p+1, q, r+1)
    f(p, q-1, r+1)
    f(p, q+1, r+1)

for i in range(6):
    for j in range(6):
        if ord(a[i][j]) == 49:
            f(i, j, 1)
print(b)
